        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Rabbiniz: \"Bana dua edin ki duanıza icabet edeyim. Bana kulluk etmeyi büyüklüklerine yediremeyenler alçalmış olarak cehenneme gireceklerdir\" buyurmuştur"
        }
