        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "İşte herşeyin yaratıcısı olan Rabbiniz Allah budur. O'ndan başka tanrı yoktur. Nasıl aldatılıp döndürülürsünüz"
        }
